SELECT CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, s.city, SUM(ss.revenue) AS total_revenue, ROUND(AVG(ss.units), 2) AS avg_units FROM store_sales ss RIGHT JOIN products p ON ss.product_id = p.id FULL OUTER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END, s.city ORDER BY avg_units DESC;
